#!/bin/bash
# Stub harness: exercise pi_clean.sh system sections in mode
# (extracted verbatim from the script) against the base_fix fixture,
# with maybe_root/confirm/rm stubbed (defined AFTER sourcing) so a
# non-root sandbox can "y" to everything and we check exactly what
# would be offered + deleted.
set -u
HERE=$(cd "$(dirname "$0")" && pwd)
SRC=$(cd "$HERE/.." && pwd)/pi_clean.sh
# shared rootfs fixture (regenerated by make_base_fix.sh when missing)
[[ -e /tmp/pi_clean_test/base_fix/etc/os-release ]] || bash "$HERE/make_base_fix.sh"
F=/tmp/pi_clean_test/base_fix
CONF=/tmp/pi_clean_test/base_confirms
RML=/tmp/pi_clean_test/base_rms
: > "$CONF"; : > "$RML"

# ---- extract: shared helpers + all collection sections (stop before MAIN) ----
# (ends at the [11] MAIN banner so the runbook/summary are excluded)
awk '/^CLEAN_COUNT=0$/{f=1} f{print} /\[11\]/{if(f)exit}' "$SRC" \
    > /tmp/pi_clean_test/base_extract.sh
grep -q 'sec_flatpak()' /tmp/pi_clean_test/base_extract.sh || { echo NO-EXTRACT; exit 1; }

# base-mode env (BASE read dynamically inside the functions)
BASE="$F" QUIET=0 TOTAL=0 DRY=0 IS_ROOT=1

source /tmp/pi_clean_test/base_extract.sh

# ---- stubs (must override the sourced definitions) --------------------
maybe_root() { return 0; }              # pretend we are root
confirm() {
    local t="$1" s="$2"
    if (( s <= 0 )); then
        printf 'NOCLEAN %s\n' "$t"
        return 1
    fi
    printf 'OFFER  %-30s %s bytes\n' "$t" "$s" >> "$CONF"
    return 0                            # user says y
}
rm() {
    local a
    for a in "$@"; do
        case $a in -f|-rf|--) ;; *) printf '%s\n' "$a" >> "$RML";; esac
    done
    return 0
}

# ---- run each system section in base mode ------------------------------
for sec in sec_temptmp sec_rotlog sec_kernels sec_cores sec_apt_lists \
           sec_apt_cache sec_journal sec_flatpak; do
    "$sec"
done
echo "===== offers (title, bytes) ====="
cat "$CONF"
echo "===== NOCLEAN sections ====="
echo "(see interactive output above if any)"
echo "===== rm targets ====="
cat "$RML"

# ---- verdicts -----------------------------------------------------------
KNEW=6.18.50+rpi-v8
KOLD=6.12.47+rpi-v8
fail=0
pass() { echo "PASS: $1"; }
ffail() { echo "FAIL: $1"; fail=1; }
has() { grep -qF -- "$1" "$2"; }

has "old kernel artifacts" "$CONF"       && pass "kernels offered"        || ffail "kernels offered"
has "flatpak unused runtimes" "$CONF"    && pass "flatpak offered"        || ffail "flatpak offered"
has "systemd journal" "$CONF"            && pass "journal offered"        || ffail "journal offered"
has "APT package cache" "$CONF"         && pass "apt cache offered"      || ffail "apt cache offered"
FPAK_SIZE=$(awk '/flatpak unused/{print $(NF-1)}' "$CONF")
[[ "$FPAK_SIZE" == 4194326 ]] && pass "flatpak offer size exact (4MB+metadata)" || ffail "flatpak offer size exact (got: $FPAK_SIZE)"
has "APT package index" "$CONF"          && pass "apt lists offered"      || ffail "apt lists offered"
has "stale temp files" "$CONF"           && pass "temptmp offered"        || ffail "temptmp offered"
has "rotated log files" "$RML"           && pass "rotlog files targeted"  || :
has "$F/tmp/stale" "$RML"                && pass "stale tmp rm'd"         || ffail "stale tmp rm'd"
has "$F/var/log/journal/old.journal" "$RML" && pass "old journal seg rm'd" || ffail "old journal seg rm'd"
has "fresh.journal" "$RML"               && ffail "fresh journal kept"   || pass "fresh journal kept"
has "$KNEW" "$RML"                       && ffail "newest kernel kept"   || pass "newest kernel kept"
has "$KOLD" "$RML"                       && pass "old kernel rm'd"        || ffail "old kernel rm'd"
has "org.kde.Platform" "$RML"            && pass "unused runtime rm'd"    || ffail "unused runtime rm'd"
has "org.freedesktop.Platform" "$RML"    && ffail "referenced runtime kept" || pass "referenced runtime kept"
has "org.freedesktop.Sdk" "$RML"         && ffail "referenced SDK kept"     || pass "referenced SDK kept"
has "PeaZip" "$RML"                      && ffail "flatpak app kept"     || pass "flatpak app kept"
has "$F/var/cache/apt/archives/foo.deb" "$RML" && pass "apt deb rm'd"    || ffail "apt deb rm'd"
has "$F/var/lib/apt/lists" "$RML"        && pass "apt lists rm'd"        || ffail "apt lists rm'd"

# ---- prefix-trap test in BASE mode (unit: is_current strictness) --------
echo
echo "===== trap: running 6.12.15 must not hold back 6.12.150 ====="
G=/tmp/pi_clean_test/kern_trap
rm -rf "$G"; mkdir -p "$G/boot" "$G/etc"
T1="6.12.15-rpi-v8"; T2="6.12.150-amd64"
for v in "$T1" "$T2"; do
    head -c 100000 /dev/zero > "$G/boot/config-$v"
    head -c 100000 /dev/zero > "$G/boot/initrd.img-$v"
done
touch -d '2026-10-28 12:00' "$G/boot/config-$T1" "$G/boot/initrd.img-$T1"
touch -d '2026-10-01 09:00' "$G/boot/config-$T2" "$G/boot/initrd.img-$T2"
CONF_T=/tmp/pi_clean_test/kern_trap_conf; RML_T=/tmp/pi_clean_test/kern_trap_rms
CONF=$CONF_T; RML=$RML_T; : > "$CONF"; : > "$RML"
BASE=$G IS_ROOT=1
sec_kernels
echo "offer: $(cat "$CONF_T")"
echo "rm:    $(tr '\n' ' ' < "$RML_T")"
has "$G/boot/config-$T2" "$RML_T" && pass "trap: 6.12.150-amd64 offered" || ffail "trap: 6.12.150-amd64 offered"
has "$G/boot/initrd.img-$T2" "$RML_T" && pass "trap: 6.12.150 initrd too" || ffail "trap: 6.12.150 initrd too"
grep -q "200000 bytes" "$CONF_T" && pass "trap: size = exactly T2's files" || ffail "trap: size = exactly T2's files"
has "$T1" "$RML_T" && ffail "trap: 6.12.15 kept" || pass "trap: 6.12.15 kept"

# ---- live-mode kernel branch (real /boot of this box, uname stub) -------
echo
echo "===== live-mode sec_kernels (real /boot, uname stub) ====="
CONF_LIVE=/tmp/pi_clean_test/kern_confirms; RML_LIVE=/tmp/pi_clean_test/kern_rms
uname() { echo "${LIVE_KVER}"; }
run_kern() {
    CONF=$CONF_LIVE; RML=$RML_LIVE; : > "$CONF"; : > "$RML"
    BASE= IS_ROOT=1
    sec_kernels
}

# A: this host runs 6.18.50+rpt-rpi-2712 -> its +v8 variant stays,
#    6.12.75+* and 6.18.39+* are offered
LIVE_KVER="6.18.50+rpt-rpi-2712"; run_kern
ok=1
for v in 6.12.75+rpt-rpi-2712 6.12.75+rpt-rpi-v8 6.18.39+rpt-rpi-2712 6.18.39+rpt-rpi-v8; do
    has "config-$v" "$RML_LIVE" || ok=0
done
has "config-6.18.50" "$RML_LIVE" && ok=0
(( ok )) && pass "A: 6.18.50(+v8) kept, 6.12.75/6.18.39 offered" || ffail "A: 6.18.50(+v8) kept, 6.12.75/6.18.39 offered"

# B: pretend 6.12.75+rpt-rpi-2712 is running -> variants stay, the rest goes
LIVE_KVER="6.12.75+rpt-rpi-2712"; run_kern
ok=1
for v in 6.18.39+rpt-rpi-2712 6.18.39+rpt-rpi-v8 6.18.50+rpt-rpi-2712 6.18.50+rpt-rpi-v8; do
    has "config-$v" "$RML_LIVE" || ok=0
done
has "config-6.12.75" "$RML_LIVE" && ok=0
(( ok )) && pass "B: 6.12.75(+v8) kept, 6.18.39/6.18.50 offered" || ffail "B: 6.12.75(+v8) kept, 6.18.39/6.18.50 offered"

exit $fail
